12→  EventThumbnail,
13→  EventTitle,
14→} from "./_components";
15→
16→export const revalidate = 60;
17→
18→interface EventDetailPageProps {
19→  params: Promise<{ id: string }>;
20→}
21→
22→export async function generateMetadata({
23→  params,
24→}: EventDetailPageProps): Promise<Metadata> {
25→  const { id } = await params;
26→  const trpc = await createPublicServerCaller();
27→  const event = await trpc.events.getById(id);
28→
29→  if (!event) {
30→    return {
31→      title: "イベントが見つかりません",
32→    };
33→  }
34→
35→  const description =
36→    event.description?.slice(0, 120) ||
37→    "SOY-POYで開催されるイベントの詳細情報です。";
38→
39→  return {
40→    title: event.title,
41→    description,
42→    openGraph: {
43→      title: event.title,
44→      description,
45→      ...(event.thumbnail && {
46→        images: [{ url: event.thumbnail }],
47→      }),
48→    },
49→  };
50→}
51→
52→export default async function EventDetailPage({
53→  params,
54→}: EventDetailPageProps) {
55→  const { id } = await params;
56→
57→  const trpc = await createPublicServerCaller();
58→  const event = await trpc.events.getById(id);
59→
60→  if (!event) notFound();
61→
62→  return (
63→    <div className={cn("container mx-auto max-w-5xl", "px-8 md:px-16 py-8")}>
64→      <PageTitle title="Events" />
65→      <EventBreadcrumb eventTitle={event.title} />
66→
67→      <div
68→        className={cn(
69→          "grid grid-cols-1 md:grid-cols-2",
70→          "gap-4 md:gap-8",
71→          "mt-6",
72→          "font-display",
73→        )}
74→      >
75→        <EventDate date={event.date} className="order-1" />
76→        <EventTitle title={event.title} className="order-2" />
77→        <EventThumbnail
78→          src={event.thumbnail}
79→          alt={event.title}
80→          eventType={event.type}
81→          className="order-3"
82→        />
83→        <EventDescription description={event.description} className="order-4" />
84→      </div>
85→      <EventFooter />
86→    </div>
87→  );
88→}
