"use client";

import Image from "next/image";
import Link from "next/link";
import { CldImage } from "next-cloudinary";
import NoImage from "@/assets/no-image.png";
import type { EventEntity } from "@/domain/entities";
import { cn } from "@/utils/cn";
import {
  formatDayOfWeek,
  formatMonthDayOnly,
  getDayOfWeekColorClass,
} from "@/utils/date";
import { truncate } from "@/utils/text";
import { PickUpLabel } from "./PickUpLabel";

interface EventListItemProps {
  event: EventEntity;
}

export function EventListItem({ event }: EventListItemProps) {
  //TODO: 価格のロジックを修正する。
  const priceOrCondition =
    event.description?.includes("フリーカンパ") ||
    event.description?.includes("フリー")
      ? "フリーカンパ制+1ドリンク"
      : event.description?.match(/¥[\d,]+/)
        ? event.description.match(/¥[\d,]+/)?.[0]
        : null;

  return (
    <Link
      href={`/events/${event.id}`}
      className={cn(
        "relative flex",
        "gap-4 md:gap-6",
        "py-3",
        "font-display",
        "hover:bg-soypoy-secondary/5 active:bg-soypoy-secondary/5",
        "transition-colors",
        "cursor-pointer",
      )}
    >
      <div
        className={cn(
          "flex flex-shrink-0",
          "flex-col md:flex-row justify-between",
          "gap-3 md:gap-4",
          "basis-[30%] md:flex-none md:w-[250px] lg:w-[280px]",
        )}
      >
        <div>
          <div className="text-3xl md:text-4xl font-medium">
            {formatMonthDayOnly(event.date)}
          </div>
          <div
            className={cn(
              "text-base/2 md:text-lg font-semibold",
              getDayOfWeekColorClass(event.date),
            )}
          >
            {formatDayOfWeek(event.date)}
          </div>
        </div>
        {event.thumbnail ? (
          <CldImage
            src={event.thumbnail}
            alt={`${event.title}のイベントサムネイル画像`}
            className={cn("w-34 md:w-38 lg:w-42", "aspect-insta object-cover")}
            width={400}
            height={500}
            crop="fill"
            gravity="auto"
          />
        ) : (
          <Image
            src={NoImage}
            alt="イベントサムネイル画像なし"
            className={cn("w-34 md:w-38 lg:w-42", "aspect-insta object-cover")}
            width={400}
            height={500}
          />
        )}
      </div>

      <div
        className={cn("flex flex-col justify-start", "basis-[70%] md:flex-1")}
      >
        <h3 className="text-base md:text-2xl font-semibold mb-2">
          {truncate(event.title, 50)}
        </h3>

        <div className="text-soypoy-muted font-display text-sm md:text-base">
          {priceOrCondition && <p>{priceOrCondition}</p>}
        </div>
      </div>
      {event.isPickup && <PickUpLabel />}
    </Link>
  );
}

import { CldImage } from "next-cloudinary";
import { EventStatusBadge } from "@/components/admin/EventStatusBadge";
import { Badge } from "@/components/shadcn/badge";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/shadcn/card";
import type { EventEntity } from "@/domain/entities";
import { formatDateJP } from "@/utils/date";

interface EventDetailCardProps {
  event: EventEntity;
}

export function EventDetailCard({ event }: EventDetailCardProps) {
  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>{event.title}</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div className="space-y-4">
              <DetailItem label="ID">{event.id}</DetailItem>

              <DetailItem label="日付">{formatDateJP(event.date)}</DetailItem>

              <DetailItem label="時間">
                {`開場 ${event.openTime} / 開始 ${event.startTime}`}
              </DetailItem>

              <DetailItem label="種類">
                <Badge variant="outline">{event.type}</Badge>
              </DetailItem>

              <DetailItem label="公開ステータス">
                <EventStatusBadge variant={event.publicationStatus} />
              </DetailItem>

              <DetailItem label="ピックアップ">
                <Badge variant={event.isPickup ? "default" : "secondary"}>
                  {event.isPickup ? "ON" : "OFF"}
                </Badge>
              </DetailItem>

              {event.description && (
                <DetailItem label="説明">
                  <p className="whitespace-pre-wrap">{event.description}</p>
                </DetailItem>
              )}
            </div>

            <div>
              {event.thumbnail && (
                <DetailItem label="サムネイル">
                  {/* NOTE: Cloudinaryの画像のためCldImageを使用 */}
                  <CldImage
                    src={event.thumbnail}
                    alt={event.title}
                    width={400}
                    height={500}
                    crop="fill"
                    gravity="auto"
                    className="rounded-md border object-cover w-full aspect-insta"
                  />
                </DetailItem>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {(event.pricing?.length ||
        event.performers?.length ||
        event.hashtags?.length) && (
        <Card>
          <CardHeader>
            <CardTitle>イベント詳細</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            {event.pricing && event.pricing.length > 0 && (
              <DetailItem label="料金">
                <table className="text-sm w-full">
                  <thead>
                    <tr className="border-b">
                      <th className="text-left py-1 pr-4 font-medium">区分</th>
                      <th className="text-right py-1 pr-4 font-medium">金額</th>
                      <th className="text-left py-1 font-medium">備考</th>
                    </tr>
                  </thead>
                  <tbody>
                    {event.pricing.map((tier) => (
                      <tr key={tier.label} className="border-b last:border-0">
                        <td className="py-1 pr-4">{tier.label}</td>
                        <td className="py-1 pr-4 text-right">
                          {tier.amount.toLocaleString()}円
                        </td>
                        <td className="py-1">{tier.note}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </DetailItem>
            )}

            {event.performers && event.performers.length > 0 && (
              <DetailItem label="出演者">
                <ul className="space-y-1">
                  {event.performers.map((performer) => (
                    <li
                      key={performer.name}
                      className="flex items-center gap-2"
                    >
                      <span>{performer.name}</span>
                      {performer.role && (
                        <Badge variant="outline">{performer.role}</Badge>
                      )}
                      {performer.instagramHandle && (
                        <span className="text-muted-foreground">
                          @{performer.instagramHandle}
                        </span>
                      )}
                    </li>
                  ))}
                </ul>
              </DetailItem>
            )}

            {event.hashtags && event.hashtags.length > 0 && (
              <DetailItem label="ハッシュタグ">
                <div className="flex flex-wrap gap-2">
                  {event.hashtags.map((tag) => (
                    <Badge key={tag} variant="secondary">
                      #{tag}
                    </Badge>
                  ))}
                </div>
              </DetailItem>
            )}
          </CardContent>
        </Card>
      )}
    </div>
  );
}

function DetailItem({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) {
  return (
    <div>
      <h3 className="text-sm font-medium text-muted-foreground mb-1">
        {label}
      </h3>
      <div className="text-sm">{children}</div>
    </div>
  );
}

