 1→/**
 2→ * URLを検出して分割する
 3→ * テキスト内のURLを検出し、テキスト部分とURL部分に分割して返す
 4→ */
 5→
 6→export interface TextSegment {
 7→  type: "text" | "url";
 8→  content: string;
 9→}
10→
11→// URL検出用の正規表現
12→// http/https URLを検出
13→const URL_REGEX =
14→  /(https?:\/\/(?:[-\w@:%.+~#=]{1,256}\.)+[a-zA-Z0-9()]{1,6}\b(?:[-\w()@:%+.~#?&/=]*))/gi;
15→
16→/**
17→ * テキストをURLとテキストに分割する
18→ */
19→export function parseTextWithUrls(text: string): TextSegment[] {
20→  const segments: TextSegment[] = [];
21→  let lastIndex = 0;
22→
23→  const matches = text.matchAll(URL_REGEX);
24→
25→  for (const match of matches) {
26→    const url = match[0];
27→    const matchIndex = match.index ?? 0;
28→
29→    // URL前のテキストがあれば追加
30→    if (matchIndex > lastIndex) {
31→      segments.push({
32→        type: "text",
33→        content: text.slice(lastIndex, matchIndex),
34→      });
35→    }
36→
37→    // URLを追加
38→    segments.push({
39→      type: "url",
40→      content: url,
41→    });
42→
43→    lastIndex = matchIndex + url.length;
44→  }
45→
46→  // 残りのテキストがあれば追加
47→  if (lastIndex < text.length) {
48→    segments.push({
49→      type: "text",
50→      content: text.slice(lastIndex),
51→    });
52→  }
53→
54→  // マッチがなかった場合は全体をテキストとして返す
55→  if (segments.length === 0) {
56→    segments.push({
57→      type: "text",
58→      content: text,
59→    });
60→  }
61→
62→  return segments;
63→}
64→
65→/**
66→ * テキストにURLが含まれているかチェック
67→ */
68→export function hasUrl(text: string): boolean {
69→  return URL_REGEX.test(text);
70→}
